def digest_register(value, reg_type):
    if reg_type == 'INT':
        trailing = trailing_zeros(value) % 64
        leading = leading_zeros(value) % 64
        return (trailing & 0x3F) ^ ((leading & 0x3F) << 3) ^ ((value & 0x3F) << 6)
    elif reg_type == 'FP64':
        return ((value >> 55) & 0x1FF) << 3
    elif reg_type == 'FP32':
        return ((value >> 26) & 0x3F) << 3
    elif reg_type == 'FP16':
        return ((value >> 13) & 0x7) << 3
    elif reg_type == 'FLAG':
        return (value & 0xF) | ((value & 0xF) << 4) | ((value & 0xF) << 8)
    else:
        return 0

def allocate_tomasulo(reg_id, rob_index):
    tomasulo_table[reg_id].payload = rob_index
    tomasulo_table[reg_id].valid = 0

def decode_tick():
    for reg in range(num_logical_regs):
        if tomasulo_table[reg].valid == 1:
            if tomasulo_table[reg].decay_ctr > 0:
                tomasulo_table[reg].decay_ctr -= 1
            if tomasulo_table[reg].decay_ctr == 0:
                tomasulo_table[reg].valid = 0

def complete_tomasulo(reg_id, rob_index, value, reg_type):
    if tomasulo_table[reg_id].valid == 0 and tomasulo_table[reg_id].payload == rob_index:
        tomasulo_table[reg_id].payload = digest_register(value, reg_type)
        tomasulo_table[reg_id].valid = 1
        tomasulo_table[reg_id].decay_ctr = decay_timeout - 1

def mispredict_recovery(squashed_rob_indices):
    for reg in range(num_logical_regs):
        if tomasulo_table[reg].valid == 0 and tomasulo_table[reg].payload in squashed_rob_indices:
            tomasulo_table[reg].valid = 1
            tomasulo_table[reg].payload = digest_register(arch_reg_value(reg), arch_reg_type(reg))
            tomasulo_table[reg].decay_ctr = decay_timeout - 1
